import 'package:flutter_test/flutter_test.dart';
import 'package:printer_hub/moonraker.dart';

void main() {
  test('reads Creality Print / Orca header and summary (the K2 reports nothing)', () {
    final m = gcodeMeta('''
; HEADER_BLOCK_START
; generated by Creality_Print V7.3.0.6157 on 2026-10-29 at 21:28:39
; HEADER_BLOCK_END
G1 X1
;TIME_ELAPSED:5304.38
; EXECUTABLE_BLOCK_END
; filament used [mm] = 0.00, 1358.87, 1516.67
; filament used [g] = 0.00, 4.09, 4.56
; total filament used [g] = 21.32
; estimated printing time (normal mode) = 1h 28m 17s
; CONFIG_BLOCK_START
; filament_colour = #ffa800;#3ddf57;#ff1e1e
; filament_notes = 
; filament_type = PLA;PLA;PETG
; layer_height = 0.2
''');
    expect(m['slicer'], 'Creality Print');
    expect(m['slicer_version'], '7.3.0.6157');
    expect(m['estimated_time'], 5297);
    expect(m['filament_total'], closeTo(2875.54, 0.01));
    expect(m['filament_weight'], [0.0, 4.09, 4.56]);
    expect(m['filament_weight_total'], 21.32);
    expect(m['filament_type'], 'PLA;PLA;PETG');
    expect(m['filament_colour'], '#ffa800;#3ddf57;#ff1e1e');
    expect(m['layer_height'], 0.2);
  });

  test('reads OrcaSlicer and Cura', () {
    final orca = gcodeMeta('; generated by OrcaSlicer 2.5.0 on 2026-11-09 at 18:16:09\n'
        '; estimated printing time (normal mode) = 1d 2h 3m 4s\n');
    expect([orca['slicer'], orca['slicer_version'], orca['estimated_time']], ['OrcaSlicer', '2.5.0', 93784]);
    final cura = gcodeMeta(';FLAVOR:Marlin\n;TIME:5283\n;Filament used: 1.5m\n;Layer height: 0.16\n'
        ';Generated with Cura_SteamEngine 5.7.0\n');
    expect([cura['slicer'], cura['estimated_time'], cura['filament_total'], cura['layer_height']],
        ['Cura', 5283, 1500.0, 0.16]);
    expect(gcodeMeta('G1 X1\n'), isEmpty);
  });
}
